from pathlib import Path
import base64

ROOT = Path.cwd()

if not (ROOT / "package.json").exists():
    raise SystemExit("ERROR: Run this from the sepulchria-portal repository root.")

FILES = {'app/(portal)/admin/jobs/page.tsx': '', 'app/(portal)/admin/jobs/actions.ts': '', 'components/portal/admin-jobs-context.tsx': ''}

for relative, encoded in FILES.items():
    path = ROOT / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(base64.b64decode(encoded).decode(), encoding="utf-8")

def patch(path, old, new, label):
    text = path.read_text(encoding="utf-8")
    if new in text:
        return
    if old not in text:
        raise SystemExit(f"ERROR: Could not find current block: {label}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")

layout = ROOT / "app/(portal)/admin/layout.tsx"
patch(
    layout,
    '            <AdminNavigationLink href="/admin/items">\n              Items\n            </AdminNavigationLink>\n',
    '            <AdminNavigationLink href="/admin/items">\n              Items\n            </AdminNavigationLink>\n\n            <AdminNavigationLink href="/admin/jobs">\n              Jobs\n            </AdminNavigationLink>\n',
    "Admin Jobs navigation",
)

sidebar = ROOT / "components/portal/portal-responsive-right-sidebar.tsx"
patch(
    sidebar,
    'import { AdminRecordSearchContext } from "@/components/portal/admin-record-search-context";\n',
    'import { AdminRecordSearchContext } from "@/components/portal/admin-record-search-context";\nimport { AdminJobsContext } from "@/components/portal/admin-jobs-context";\n',
    "AdminJobsContext import",
)

patch(
    sidebar,
    '  const isAdminItemsPath =\n    pathname === "/admin/items";\n\n  const isAdminLocationsPath =\n',
    '  const isAdminItemsPath =\n    pathname === "/admin/items";\n\n  const isAdminJobsPath =\n    pathname === "/admin/jobs";\n\n  const isAdminLocationsPath =\n',
    "Admin Jobs pathname",
)

patch(
    sidebar,
    '              ) : isAdminItemsPath ? (\n                <AdminRecordSearchContext\n                  key={`items-${adminRevision}`}\n                  mode="items"\n                />\n              ) : isAdminLocationsPath ? (\n',
    '              ) : isAdminItemsPath ? (\n                <AdminRecordSearchContext\n                  key={`items-${adminRevision}`}\n                  mode="items"\n                />\n              ) : isAdminJobsPath ? (\n                <AdminJobsContext\n                  key={`jobs-${adminRevision}`}\n                />\n              ) : isAdminLocationsPath ? (\n',
    "Admin Jobs sidebar branch",
)

print("SUCCESS")
print("Admin > Jobs installed.")
print("No SQL required.")
print("Run: npm run build")
